// =======================================================================================================
// Fixed cases (NumPy results)
// =======================================================================================================

// *******************************************************************************************************
static void test_get_numpy_cases(void){

    int c, variant, bad = 0, bad_ref = 0, bad_flags = 0;

    for (c = 0; c < N_GET_CASES; c++){
        const getcase_t* g = &k_get[c];
        nd_index_t items[6];
        ndarr_t arrs[6];
        int64_t rs[OTI_ND_MAXDIM];
        int32_t rnd = 0;

        memset(arrs, 0, sizeof(arrs));
        build_items(g->items, g->nitems, items, arrs);
        // the reference agrees with NumPy on this case
        {
            int st = ref_adv(g->nd, g->shape, g->nitems, items, &rnd, rs);
            int64_t q;
            int ok = (st == 0 && rnd == g->rnd);
            for (q = 0; ok && q < g->rnd; q++){
                ok = ok && rs[q] == g->rshape[q];
            }
            for (q = 0; ok && q < g->nvals; q++){
                ok = ok && (double)g_lin[q] == g->vals[q];
            }
            if (!ok){
                bad_ref++;
                fprintf(stderr, "  reference disagrees with NumPy on %s\n", g->name);
            }
        }
        for (variant = 0; variant < 3; variant++){
            ndarr_t base = {0}, src = {0}, res = {0};
            int st;
            make_src(g->nd, g->shape, variant, &base, &src);
            st = nd_index_get(NULL, &src, g->nitems, items, &res);
            if (st != OTI_OK || !values_equal(&res, g->rnd, g->rshape, g->vals, g->nvals)){
                bad++;
                fprintf(stderr, "  get %s (source variant %d): status %d\n", g->name, variant, st);
            } else if (g->nvals > 1 && !(res.flags & ND_C_CONTIG)){
                bad_flags++;
            }
            if (res.buf != NULL){
                nd_release(&res);
            }
            nd_release(&base);
        }
    }
    check(bad_ref == 0,
            "the reference implementation reproduces every NumPy result of the fixed get cases");
    check(bad == 0,
            "nd_index_get: the fixed NumPy cases (C, F, strided sources): NumPy's shape and values");
    check(bad_flags == 0, "nd_index_get: results are C-contiguous");

}
// -------------------------------------------------------------------------------------------------------


// *******************************************************************************************************
static void test_set_numpy_cases(void){

    int c, variant, bad = 0, bad_guard = 0, bad_ref = 0;

    for (c = 0; c < N_SET_CASES; c++){
        const setcase_t* s = &k_set[c];
        nd_index_t items[6];
        ndarr_t arrs[6];
        int64_t n = shape_size(s->nd, s->shape), nv = shape_size(s->vnd, s->vshape), q;
        int64_t rs[OTI_ND_MAXDIM];
        int32_t rnd = 0;

        memset(arrs, 0, sizeof(arrs));
        build_items(s->items, s->nitems, items, arrs);
        for (variant = 0; variant < 3; variant++){
            ndarr_t base = {0}, dst = {0}, vals = {0};
            int st, ok = 1;
            make_view(s->nd, s->shape, variant, OTI_F64, &base, &dst);
            canary_base(&base);
            for (q = 0; q < n; q++){
                set_f(&dst, q, (double)q);
            }
            nd_alloc(NULL, s->vdt, s->vnd, s->vshape, ND_LAYOUT_C, 0, &vals);
            for (q = 0; q < nv; q++){
                set_num(&vals, q, s->vdata[q]);
            }
            st = nd_index_set(NULL, &dst, s->nitems, items, &vals);
            if (st != OTI_OK){
                ok = 0;
            } else {
                for (q = 0; q < n; q++){
                    ok = ok && get_f(&dst, q) == s->expect[q];
                }
            }
            if (!ok){
                bad++;
                fprintf(stderr, "  set %s (dst variant %d): status %d\n", s->name, variant, st);
            }
            if (st == OTI_OK && !canary_ok(&base, &dst)){
                bad_guard++;
            }
            nd_release(&vals);
            nd_release(&base);
        }
        (void)ref_adv(s->nd, s->shape, s->nitems, items, &rnd, rs);
        (void)bad_ref;
    }
    check(bad == 0,
            "nd_index_set: the fixed NumPy cases (duplicates, broadcast values, masks) match NumPy");
    check(bad_guard == 0,
            "nd_index_set: only the destination view is written (canaries around padded / strided dst)");

}
