// =======================================================================================================
// Randomized agreement with the reference
// =======================================================================================================

// *******************************************************************************************************
// A random index array view of `shape` (I64 or U8 dtype) in a random layout.
static void make_index_array(int32_t nd, const int64_t* shape, int32_t dtype, ndarr_t* base,
        ndarr_t* view){

    make_view(nd, shape, (int)rng_int(3), dtype, base, view);

}
// -------------------------------------------------------------------------------------------------------


typedef struct {
    int32_t nd;
    int64_t shape[4];
    int32_t nidx;
    nd_index_t items[8];
    ndarr_t bases[8], views[8];
    int expect_oor;
} rcase_t;

// *******************************************************************************************************
// Draws a random valid-ish index list for a source of shape sshape.
static void random_case(int32_t nd, const int64_t* sshape, rcase_t* rc, int allow_bad){

    int32_t types[8], mdim[8], n = 0, consumed = 0, i, k;
    int32_t ell_pos = -1;
    int32_t ax;
    int have_arr = 0;
    int64_t bshape[2];
    int32_t bnd = (int32_t)rng_int(3);
    int any_empty = 0;

    memset(rc, 0, sizeof(*rc));
    rc->nd = nd;
    for (k = 0; k < nd; k++){
        rc->shape[k] = sshape[k];
    }
    for (k = 0; k < bnd; k++){
        bshape[k] = 1 + rng_int(3);
    }
    // types: 0 int, 1 slice, 2 newaxis, 3 I64 array, 4 mask
    while (n < 5 && consumed < nd && rng_int(4) != 0){
        int t = (int)rng_int(6);
        t = (t == 5) ? 3 : t;
        if (t == 4){
            int32_t m = 1 + (int32_t)rng_int(2);
            if (consumed + m > nd){
                t = 3;
            } else {
                mdim[n] = m;
            }
        }
        types[n] = t;
        if (t == 0 || t == 1 || t == 3){
            consumed++;
        } else if (t == 4){
            consumed += mdim[n];
        }
        if (t == 3 || t == 4){
            have_arr = 1;
        }
        n++;
    }
    if (!have_arr){
        types[n] = 3;
        n++;
        consumed++;
        if (consumed > nd){
            // too many: replace a consuming item by the array
            for (i = 0; i < n - 1; i++){
                if (types[i] == 0 || types[i] == 1){
                    types[i] = 3;
                    n--;
                    consumed--;
                    break;
                }
            }
        }
    }
    if (consumed > nd){
        n--;
        consumed--;
        types[n - 1] = 3;
    }
    // optional ellipsis
    if (rng_int(3) == 0 && n < 7){
        ell_pos = (int32_t)rng_int(n + 1);
        for (i = n; i > ell_pos; i--){
            types[i] = types[i - 1];
            mdim[i] = mdim[i - 1];
        }
        types[ell_pos] = 9;
        n++;
    }
    // generate items with their target axes
    ax = 0;
    for (i = 0; i < n; i++){
        nd_index_t* it = &rc->items[i];
        int64_t ext = (ax < nd) ? sshape[ax] : 1;
        memset(it, 0, sizeof(*it));
        if (types[i] == 9){
            it->kind = ND_IDX_ELLIPSIS;
            ax += nd - consumed;
        } else if (types[i] == 2){
            it->kind = ND_IDX_NEWAXIS;
        } else if (types[i] == 0){
            it->kind = ND_IDX_INT;
            it->start = ext > 0 ? rng_int(2 * ext) - ext : 0;
            if (ext == 0){
                it->kind = ND_IDX_SLICE;
            }
            ax++;
        } else if (types[i] == 1){
            int has = (int)rng_int(8);
            int64_t step = rng_int(7) - 3;
            if ((has & HT) && step == 0){
                step = -1;
            }
            it->kind = ND_IDX_SLICE;
            it->has = has;
            it->start = rng_int(2 * ext + 4) - (ext + 2);
            it->stop = rng_int(2 * ext + 4) - (ext + 2);
            it->step = step;
            ax++;
        } else if (types[i] == 3){
            int64_t ash[2];
            int32_t and_ = bnd;
            int64_t q, cnt;
            int empty = 0;
            for (k = 0; k < and_; k++){
                ash[k] = (rng_int(3) == 0) ? 1 : bshape[k];
            }
            if (and_ > 0 && (ext == 0 || rng_int(12) == 0)){
                ash[0] = 0;
                empty = 1;
            } else if (and_ == 0 && ext == 0){
                and_ = 1;
                ash[0] = 0;
                empty = 1;
            }
            any_empty = any_empty || empty;
            make_index_array(and_, ash, OTI_I64, &rc->bases[i], &rc->views[i]);
            cnt = shape_size(and_, ash);
            for (q = 0; q < cnt; q++){
                set_num(&rc->views[i], q, (double)(ext > 0 ? rng_int(2 * ext) - ext : 0));
            }
            it->kind = ND_IDX_ARRAY;
            it->arr = &rc->views[i];
            ax++;
        } else {
            int32_t m = mdim[i];
            int64_t msh[2];
            int64_t q, cnt;
            for (k = 0; k < m; k++){
                msh[k] = sshape[ax + k];
            }
            if (allow_bad && rng_int(10) == 0){
                msh[0] += 1;
            }
            make_index_array(m, msh, OTI_U8, &rc->bases[i], &rc->views[i]);
            cnt = shape_size(m, msh);
            for (q = 0; q < cnt; q++){
                set_num(&rc->views[i], q, rng_int(3) == 0 ? 1.0 : 0.0);
            }
            it->kind = ND_IDX_ARRAY;
            it->arr = &rc->views[i];
            ax += m;
        }
    }
    rc->nidx = n;
    // a deliberate out-of-range value in a non-empty configuration
    if (allow_bad && !any_empty && rng_int(12) == 0){
        for (i = 0; i < n; i++){
            if (rc->items[i].kind == ND_IDX_ARRAY && rc->views[i].dtype == OTI_I64 &&
                    nd_size(&rc->views[i]) > 0){
                set_num(&rc->views[i], 0, 1000.0);
                rc->expect_oor = 1;
                break;
            }
        }
    }

}
// -------------------------------------------------------------------------------------------------------


// *******************************************************************************************************
static void free_case(rcase_t* rc){

    int32_t i;

    for (i = 0; i < rc->nidx; i++){
        if (rc->bases[i].buf != NULL){
            nd_release(&rc->bases[i]);
        }
    }

}
// -------------------------------------------------------------------------------------------------------


// *******************************************************************************************************
static void dump_case(const rcase_t* rc){

    int32_t i, k;

    fprintf(stderr, "    source shape (");
    for (k = 0; k < rc->nd; k++){
        fprintf(stderr, "%lld ", (long long)rc->shape[k]);
    }
    fprintf(stderr, ")\n");
    for (i = 0; i < rc->nidx; i++){
        const nd_index_t* it = &rc->items[i];
        if (it->kind == ND_IDX_ARRAY){
            int64_t n = shape_size(it->arr->ndim, it->arr->shape), q;
            fprintf(stderr, "    item %d: %s shape (", i, it->arr->dtype == OTI_U8 ? "mask" : "array");
            for (k = 0; k < it->arr->ndim; k++){
                fprintf(stderr, "%lld ", (long long)it->arr->shape[k]);
            }
            fprintf(stderr, ") values");
            for (q = 0; q < n && q < 8; q++){
                fprintf(stderr, " %g", get_num(it->arr, q));
            }
            fprintf(stderr, "\n");
        } else {
            fprintf(stderr, "    item %d: kind %d has %d start %lld stop %lld step %lld\n", i, it->kind,
                    it->has,
                    (long long)it->start, (long long)it->stop, (long long)it->step);
        }
    }

}
