// *******************************************************************************************************
static void test_get_random(void){

    int iter, fails = 0, n_ok = 0, n_err = 0, n_adv_first = 0;

    rng_seed(20261103);
    for (iter = 0; iter < 4000; iter++){
        int32_t nd = 1 + (int32_t)rng_int(4), k;
        int64_t sh[4];
        rcase_t rc;
        ndarr_t base = {0}, src = {0}, res = {0};
        int32_t rnd = 0;
        int64_t rs[OTI_ND_MAXDIM];
        int expect, st;
        int64_t total;

        for (k = 0; k < nd; k++){
            sh[k] = (rng_int(10) == 0) ? 0 : 1 + rng_int(5);
        }
        random_case(nd, sh, &rc, 1);
        make_src(nd, sh, (int)rng_int(3), &base, &src);
        expect = ref_adv(nd, sh, rc.nidx, rc.items, &rnd, rs);
        if (expect == 0){
            total = shape_size(rnd, rs);
            if (total > 30000){
                free_case(&rc);
                nd_release(&base);
                continue;
            }
        }
        st = nd_index_get(NULL, &src, rc.nidx, rc.items, &res);
        if (expect != 0){
            n_err++;
            if (st != expect || res.buf != NULL){
                fails++;
                if (fails < 6){
                    fprintf(stderr, "  get iter %d: expected status %d, got %d\n", iter, expect, st);
                    dump_case(&rc);
                }
            }
        } else {
            int64_t q;
            int ok = (st == OTI_OK) && res.ndim == rnd;
            n_ok++;
            for (k = 0; ok && k < rnd; k++){
                ok = ok && res.shape[k] == rs[k];
            }
            for (q = 0; ok && q < total; q++){
                ok = ok && get_f(&res, q) == (double)g_lin[q];
            }
            if (!ok){
                fails++;
                if (fails < 6){
                    fprintf(stderr, "  get iter %d: status %d nd %d nidx %d wrong shape / values\n", iter,
                            st, nd,
                            rc.nidx);
                    dump_case(&rc);
                }
            }
            if (rnd > 0 && total > 1 && !(res.flags & ND_C_CONTIG)){
                fails++;
            }
            if (rc.nidx > 0 && rc.items[0].kind == ND_IDX_ARRAY){
                n_adv_first++;
            }
        }
        if (res.buf != NULL){
            nd_release(&res);
        }
        free_case(&rc);
        nd_release(&base);
    }
    check(fails == 0, "nd_index_get: 4000 random index lists (all item kinds) vs the reference");
    check(n_ok > 1500 && n_err > 100, "the random get cases cover both successes and the error statuses");
    (void)n_adv_first;

}
