// *******************************************************************************************************
static void test_set_random(void){

    int iter, fails = 0, n_ok = 0, guard_fail = 0, n_dup = 0;

    rng_seed(77031);
    for (iter = 0; iter < 3000; iter++){
        int32_t nd = 1 + (int32_t)rng_int(4), k;
        int64_t sh[4];
        rcase_t rc;
        ndarr_t base = {0}, dst = {0}, vb = {0}, vals = {0};
        int32_t rnd = 0;
        int64_t rs[OTI_ND_MAXDIM];
        int expect, st;
        int64_t total, n, q;
        int32_t vnd = 0;
        int64_t vsh[OTI_ND_MAXDIM];
        int32_t vdt = (int32_t)(OTI_F64 + (int)rng_int(3) * 0);
        int bad_values = 0;
        double* ref_dst;
        static double refbuf[1 << 12];

        for (k = 0; k < nd; k++){
            sh[k] = (rng_int(10) == 0) ? 0 : 1 + rng_int(4);
        }
        random_case(nd, sh, &rc, 0);
        n = shape_size(nd, sh);
        if (n > 4000){
            free_case(&rc);
            continue;
        }
        expect = ref_adv(nd, sh, rc.nidx, rc.items, &rnd, rs);
        if (expect != 0){
            free_case(&rc);
            continue;
        }
        total = shape_size(rnd, rs);
        if (total > 3000){
            free_case(&rc);
            continue;
        }
        // values: a shape broadcastable to the result shape (drop leading axes, ones), sometimes invalid
        vnd = (int32_t)rng_int(rnd + 1);
        for (k = 0; k < vnd; k++){
            vsh[k] = (rng_int(3) == 0) ? 1 : rs[rnd - vnd + k];
        }
        if (vnd > 0 && rng_int(15) == 0 && rs[rnd - 1] > 0){
            vsh[vnd - 1] = rs[rnd - 1] + 1;    // neither 1 nor the result extent: not broadcastable
            bad_values = 1;
        }
        vdt = (int32_t)(rng_int(3) == 0 ? OTI_I64 : (rng_int(2) ? OTI_F64 : OTI_U8));
        make_view(vnd, vsh, (int)rng_int(3), vdt, &vb, &vals);
        {
            int64_t nv = shape_size(vnd, vsh);
            for (q = 0; q < nv; q++){
                set_num(&vals, q, vdt == OTI_U8 ? (double)rng_int(2) : (double)(rng_int(41) - 20));
            }
        }
        make_view(nd, sh, (int)rng_int(3), OTI_F64, &base, &dst);
        canary_base(&base);
        for (q = 0; q < n; q++){
            set_f(&dst, q, (double)(1000 + q));
        }
        ref_dst = refbuf;
        for (q = 0; q < n; q++){
            ref_dst[q] = (double)(1000 + q);
        }
        if (!bad_values){
            for (q = 0; q < total; q++){
                int64_t rem = q, vlin = 0;
                int32_t kk;
                int64_t coord[16];
                for (kk = rnd - 1; kk >= 0; kk--){
                    coord[kk] = rem % rs[kk];
                    rem /= rs[kk];
                }
                for (kk = 0; kk < vnd; kk++){
                    int32_t rk = rnd - vnd + kk;
                    vlin = vlin * vsh[kk] + (vsh[kk] == 1 ? 0 : coord[rk]);
                }
                ref_dst[g_lin[q]] = get_num(&vals, vlin);
            }
            {
                // duplicates present?
                int64_t a, bq;
                int dup = 0;
                for (a = 1; a < total && !dup && a < 50; a++){
                    for (bq = 0; bq < a; bq++){
                        if (g_lin[a] == g_lin[bq]){
                            dup = 1;
                            break;
                        }
                    }
                }
                n_dup += dup;
            }
        }
        st = nd_index_set(NULL, &dst, rc.nidx, rc.items, &vals);
        if (bad_values){
            if (st != OTI_ERR_SHAPE){
                fails++;
                if (fails < 6){
                    fprintf(stderr, "  set iter %d: bad values shape gave %d; result shape (", iter, st);
                    for (k = 0; k < rnd; k++){
                        fprintf(stderr, "%lld ", (long long)rs[k]);
                    }
                    fprintf(stderr, ") values shape (");
                    for (k = 0; k < vnd; k++){
                        fprintf(stderr, "%lld ", (long long)vsh[k]);
                    }
                    fprintf(stderr, ")\n");
                    dump_case(&rc);
                }
            }
        } else {
            int ok = (st == OTI_OK);
            n_ok++;
            for (q = 0; ok && q < n; q++){
                ok = ok && get_f(&dst, q) == ref_dst[q];
            }
            if (!ok){
                fails++;
                if (fails < 6){
                    fprintf(stderr, "  set iter %d: status %d wrong values; result shape (", iter, st);
                    for (k = 0; k < rnd; k++){
                        fprintf(stderr, "%lld ", (long long)rs[k]);
                    }
                    fprintf(stderr, ") values shape (");
                    for (k = 0; k < vnd; k++){
                        fprintf(stderr, "%lld ", (long long)vsh[k]);
                    }
                    fprintf(stderr, ")\n");
                    dump_case(&rc);
                }
            }
            if (st == OTI_OK && !canary_ok(&base, &dst)){
                guard_fail++;
            }
        }
        nd_release(&vb);
        nd_release(&base);
        free_case(&rc);
    }
    check(fails == 0,
            "nd_index_set: 3000 random index lists / values shapes / dtypes / layouts vs the reference");
    check(guard_fail == 0,
            "nd_index_set: only the addressed elements change (canaries around the destination)");
    check(n_ok > 1000 && n_dup > 100, "the random set cases include duplicates and enough successes");

}
