// *******************************************************************************************************
static nd_index_t arr_item(const ndarr_t* a){

    nd_index_t it;

    memset(&it, 0, sizeof(it));
    it.kind = ND_IDX_ARRAY;
    it.arr = a;
    return it;

}
// -------------------------------------------------------------------------------------------------------


// *******************************************************************************************************
static nd_index_t int_item(int64_t v){

    nd_index_t it;

    memset(&it, 0, sizeof(it));
    it.kind = ND_IDX_INT;
    it.start = v;
    return it;

}
// -------------------------------------------------------------------------------------------------------


// *******************************************************************************************************
static nd_index_t kind_item(int kind){

    nd_index_t it;

    memset(&it, 0, sizeof(it));
    it.kind = kind;
    return it;

}
