// *******************************************************************************************************
static void test_get_errors(void){

    ndarr_t base = {0}, src = {0}, res = {0}, i1 = {0}, i2 = {0}, f1 = {0}, m1 = {0}, ib = {0}, in = {0},
            io = {0};
    int64_t sh[2] = {4, 5};
    int64_t d1[3] = {0, 2, 4}, d2[2] = {1, 3}, d3[3] = {0, 1, 2};
    int64_t s3[1] = {3}, s2[1] = {2}, s1[1] = {1};
    ndarr_t i3 = {0};
    int64_t big[1] = {4}, neg[1] = {-5}, okn[1] = {-4}, c4[1] = {4};
    double fv[2] = {0.0, 1.0};
    uint8_t mv[3] = {1, 0, 1};
    nd_index_t it[3];
    oti_ctx ctx;

    make_src(2, sh, 0, &base, &src);
    nd_wrap_trusted(d1, OTI_I64, 1, s3, NULL, 0, &i1);
    nd_wrap_trusted(d2, OTI_I64, 1, s2, NULL, 0, &i2);
    nd_wrap_trusted(d3, OTI_I64, 1, s3, NULL, 0, &i3);
    nd_wrap_trusted(fv, OTI_F64, 1, s2, NULL, 0, &f1);
    nd_wrap_trusted(mv, OTI_U8, 1, s3, NULL, 0, &m1);
    nd_wrap_trusted(big, OTI_I64, 1, s1, NULL, 0, &ib);
    nd_wrap_trusted(neg, OTI_I64, 1, s1, NULL, 0, &in);
    nd_wrap_trusted(okn, OTI_I64, 1, s1, NULL, 0, &io);

    // [0, 2, 4] on axis 0 (extent 4): 4 is out of range
    it[0] = arr_item(&i1);
    nd_init_empty(&res);
    check(nd_index_get(NULL, &src, 1, it, &res) == OTI_ERR_INDEX && res.buf == NULL,
          "a[[0,2,4]] on an axis of extent 4 -> INDEX, res empty");
    it[0] = arr_item(&ib);
    check(nd_index_get(NULL, &src, 1, it, &res) == OTI_ERR_INDEX && res.buf == NULL,
            "a[[4]] on extent 4 -> INDEX");
    it[0] = arr_item(&in);
    check(nd_index_get(NULL, &src, 1, it, &res) == OTI_ERR_INDEX && res.buf == NULL,
            "a[[-5]] on extent 4 -> INDEX");
    it[0] = arr_item(&io);
    check(nd_index_get(NULL, &src, 1, it, &res) == OTI_OK && get_f(&res, 0) == 0.0 && get_f(&res,
            4) == 4.0,
          "a[[-4]] on extent 4 is row 0");
    nd_release(&res);
    // [4] on axis 1 (extent 5) is fine; [0,2,4] there too
    it[0] = kind_item(ND_IDX_SLICE);
    it[1] = arr_item(&i1);
    check(nd_index_get(NULL, &src, 2, it, &res) == OTI_OK && res.shape[0] == 4 && res.shape[1] == 3 &&
          get_f(&res, 2) == 4.0, "a[:, [0,2,4]] on (4,5): shape (4,3), last column index 4");
    nd_release(&res);
    // float index -> DTYPE; mask shape mismatch -> INDEX; non-broadcastable -> SHAPE
    it[0] = arr_item(&f1);
    check(nd_index_get(NULL, &src, 1, it, &res) == OTI_ERR_DTYPE && res.buf == NULL,
            "a float index array -> DTYPE");
    it[0] = arr_item(&m1);
    check(nd_index_get(NULL, &src, 1, it, &res) == OTI_ERR_INDEX && res.buf == NULL,
          "a mask of shape (3,) for an axis of extent 4 -> INDEX");
    it[0] = arr_item(&i3);
    it[1] = arr_item(&i2);
    check(nd_index_get(NULL, &src, 2, it, &res) == OTI_ERR_SHAPE && res.buf == NULL,
          "index arrays of shapes (3,) and (2,) do not broadcast -> SHAPE");
    // too many items, two ellipses, step 0
    it[0] = arr_item(&i2);
    it[1] = int_item(0);
    it[2] = int_item(0);
    check(nd_index_get(NULL, &src, 3, it, &res) == OTI_ERR_INDEX,
            "three indices on a 2-D array -> INDEX");
    it[1] = kind_item(ND_IDX_ELLIPSIS);
    it[2] = kind_item(ND_IDX_ELLIPSIS);
    check(nd_index_get(NULL, &src, 3, it, &res) == OTI_ERR_INDEX, "two ellipses -> INDEX");
    it[1] = kind_item(ND_IDX_SLICE);
    it[1].has = HT;
    it[1].step = 0;
    check(nd_index_get(NULL, &src, 2, it, &res) == OTI_ERR_ARGUMENT, "a slice with step 0 -> ARGUMENT");
    // an integer item out of range next to an array
    it[0] = arr_item(&i2);
    it[1] = int_item(5);
    check(nd_index_get(NULL, &src, 2, it, &res) == OTI_ERR_INDEX && res.buf == NULL,
          "a[[1,3], 5] on (4,5) -> INDEX");
    // last error and a bad context
    oti_ctx_init(&ctx);
    it[0] = arr_item(&f1);
    check(nd_index_get(&ctx, &src, 1, it, &res) == OTI_ERR_DTYPE &&
          oti_ctx_last_error(&ctx, NULL, NULL) == OTI_ERR_DTYPE,
                  "a failing nd_index_get records its status");
    ctx.device_type = 2;
    it[0] = arr_item(&i2);
    check(nd_index_get(&ctx, &src, 1, it, &res) == oti_ctx_check(&ctx) && res.buf == NULL,
          "a bad context is rejected, res empty");
    (void)c4;
    nd_release(&base);

}
