// *******************************************************************************************************
// Sources of other dtypes: the result keeps the dtype; masks and arrays of all supported kinds.
static void test_get_dtypes_and_masks(void){

    ndarr_t bi = {0}, si = {0}, bu = {0}, su = {0}, res = {0}, ix = {0}, mk = {0};
    int64_t sh[1] = {6};
    int64_t d[3] = {5, 0, 2};
    uint8_t m[6] = {1, 0, 0, 1, 1, 0};
    int64_t s3[1] = {3};
    nd_index_t it[1];
    int64_t i;

    // I64 source: np.array([10, 11, 12, 13, 14, 15])[[5, 0, 2]] = [15, 10, 12]
    make_view(1, sh, 0, OTI_I64, &bi, &si);
    for (i = 0; i < 6; i++){
        ((int64_t*)si.data)[i] = 10 + i;
    }
    nd_wrap_trusted(d, OTI_I64, 1, s3, NULL, 0, &ix);
    it[0] = arr_item(&ix);
    check(nd_index_get(NULL, &si, 1, it, &res) == OTI_OK && res.dtype == OTI_I64 &&
            ((int64_t*)res.data)[0] == 15 &&
          ((int64_t*)res.data)[1] == 10 && ((int64_t*)res.data)[2] == 12,
                  "I64 source: the result is I64 [15, 10, 12]");
    nd_release(&res);
    // U8 source
    make_view(1, sh, 0, OTI_U8, &bu, &su);
    for (i = 0; i < 6; i++){
        ((uint8_t*)su.data)[i] = (uint8_t)(20 + i);
    }
    check(nd_index_get(NULL, &su, 1, it, &res) == OTI_OK && res.dtype == OTI_U8 &&
            ((uint8_t*)res.data)[0] == 25 &&
          ((uint8_t*)res.data)[2] == 22, "U8 source: the result is U8 [25, 20, 22]");
    nd_release(&res);
    // a mask: np.array([10..15])[[T,F,F,T,T,F]] = [10, 13, 14]
    nd_wrap_trusted(m, OTI_U8, 1, sh, NULL, 0, &mk);
    it[0] = arr_item(&mk);
    check(nd_index_get(NULL, &si, 1, it, &res) == OTI_OK && res.ndim == 1 && res.shape[0] == 3 &&
          ((int64_t*)res.data)[0] == 10 && ((int64_t*)res.data)[1] == 13 && ((int64_t*)res.data)[2] == 14,
          "mask on an I64 source: [10, 13, 14]");
    nd_release(&res);
    // a mask with nonzero values other than 1 counts as true
    {
        uint8_t m2[6] = {7, 0, 0, 255, 2, 0};
        ndarr_t mk2 = {0};
        nd_wrap_trusted(m2, OTI_U8, 1, sh, NULL, 0, &mk2);
        it[0] = arr_item(&mk2);
        check(nd_index_get(NULL, &si, 1, it, &res) == OTI_OK && res.shape[0] == 3 &&
                ((int64_t*)res.data)[1] == 13,
              "mask entries 7, 255, 2 are true (nonzero)");
        nd_release(&res);
    }
    // an index array of a non-contiguous layout (reversed) is read through its strides
    {
        ndarr_t bx = {0}, vx = {0};
        int64_t two[1] = {3};
        make_view(1, two, 2, OTI_I64, &bx, &vx);
        ((int64_t*)vx.data)[0] = 0;
        set_num(&vx, 0, 4.0); set_num(&vx, 1, 1.0); set_num(&vx, 2, 3.0);
        it[0] = arr_item(&vx);
        check(nd_index_get(NULL, &si, 1, it, &res) == OTI_OK && ((int64_t*)res.data)[0] == 14 &&
              ((int64_t*)res.data)[1] == 11 && ((int64_t*)res.data)[2] == 13,
                      "a strided / reversed index array is read in order");
        nd_release(&res);
        nd_release(&bx);
    }
    // an empty source of shape (0,) indexed by an empty array
    {
        ndarr_t e = {0}, ie = {0};
        int64_t z[1] = {0};
        nd_alloc(NULL, OTI_F64, 1, z, ND_LAYOUT_C, 0, &e);
        nd_alloc(NULL, OTI_I64, 1, z, ND_LAYOUT_C, 0, &ie);
        it[0] = arr_item(&ie);
        check(nd_index_get(NULL, &e, 1, it, &res) == OTI_OK && res.ndim == 1 && res.shape[0] == 0,
              "np.zeros(0)[np.array([], int)] is an empty (0,)");
        nd_release(&res);
        // an index into an empty axis is out of range: np.zeros(0)[[0]] -> IndexError
        nd_release(&ie);
        {
            int64_t zero[1] = {0};
            ndarr_t iz = {0};
            int64_t one_sh[1] = {1};
            nd_wrap_trusted(zero, OTI_I64, 1, one_sh, NULL, 0, &iz);
            it[0] = arr_item(&iz);
            check(nd_index_get(NULL, &e, 1, it, &res) == OTI_ERR_INDEX && res.buf == NULL,
                  "np.zeros(0)[[0]] -> INDEX (the axis is empty)");
        }
        nd_release(&e);
    }
    nd_release(&bi);
    nd_release(&bu);

}
