// *******************************************************************************************************
static void test_set_errors_and_overlap(void){

    ndarr_t base = {0}, dst = {0}, vals = {0}, i2 = {0}, f2 = {0}, ro = {0}, ov = {0};
    int64_t sh[2] = {3, 4}, s2[1] = {2};
    int64_t d2[2] = {0, 2};
    double v2[2] = {7.0, 8.0};
    nd_index_t it[2];
    int64_t i;
    oti_ctx ctx;

    make_src(2, sh, 0, &base, &dst);
    nd_wrap_trusted(d2, OTI_I64, 1, s2, NULL, 0, &i2);
    nd_wrap_trusted(v2, OTI_F64, 1, s2, NULL, 0, &f2);
    it[0] = arr_item(&i2);

    // d[[0,2]] = [7, 8] broadcasts (2,) against (2,4)? no: the values must broadcast to (2,4): (2,) does
    // not
    check(nd_index_set(NULL, &dst, 1, it, &f2) == OTI_ERR_SHAPE,
            "d[[0,2]] = (2,) into the (2,4) result -> SHAPE");
    // d[:, [0,2]] = [7, 8] broadcasts to (3,2): np.arange(12.).reshape(3,4); d[:, [0,2]] = [7., 8.]
    {
        double expect[12] = {7, 1, 8, 3, 7, 5, 8, 7, 7, 9, 8, 11};
        it[0] = kind_item(ND_IDX_SLICE);
        it[1] = arr_item(&i2);
        for (i = 0; i < 12; i++){
            set_f(&dst, i, (double)i);
        }
        check(nd_index_set(NULL, &dst, 2, it, &f2) == OTI_OK, "d[:, [0,2]] = [7, 8]");
        {
            int ok = 1;
            for (i = 0; i < 12; i++){
                ok = ok && get_f(&dst, i) == expect[i];
            }
            check(ok, "d[:, [0,2]] = [7., 8.] gives [[7,1,8,3],[7,5,8,7],[7,9,8,11]] (NumPy)");
        }
    }
    // values of a wrong dtype: F64 into an I64 destination -> DTYPE
    {
        ndarr_t bi = {0}, di = {0};
        int64_t s6[1] = {6};
        make_view(1, s6, 0, OTI_I64, &bi, &di);
        it[0] = arr_item(&i2);
        check(nd_index_set(NULL, &di, 1, it, &f2) == OTI_ERR_DTYPE,
                "F64 values into an I64 destination -> DTYPE");
        nd_release(&bi);
    }
    // read-only destination
    {
        ndarr_t d0 = {0};
        make_desc(&d0, dst.data, OTI_F64, 2, sh, dst.strides, 0);
        nd_wrap(NULL, &d0, NULL, -1, NULL, NULL, &ro);
        it[0] = arr_item(&i2);
        {
            ndarr_t row = {0};
            int64_t s24[2] = {2, 4};
            double rowv[8] = {0, 0, 0, 0, 0, 0, 0, 0};
            make_from(2, s24, ND_LAYOUT_C, rowv, &row);
            check(nd_index_set(NULL, &ro, 1, it, &row) == OTI_ERR_READONLY,
                    "scatter into a read-only destination -> READONLY");
            nd_release(&row);
        }
        nd_release(&ro);
        // an EMPTY read-only destination with an (empty) index array is READONLY too (S5)
        {
            ndarr_t e = {0}, ie = {0}, er = {0}, ed = {0};
            int64_t z[1] = {0};
            double dummy[1] = {0};
            nd_alloc(NULL, OTI_I64, 1, z, ND_LAYOUT_C, 0, &ie);
            make_desc(&ed, dummy, OTI_F64, 1, z, (int64_t[]){1}, 0);
            nd_wrap(NULL, &ed, NULL, -1, NULL, NULL, &er);
            nd_alloc(NULL, OTI_F64, 1, z, ND_LAYOUT_C, 0, &e);
            it[0] = arr_item(&ie);
            check(nd_index_set(NULL, &er, 1, it, &e) == OTI_ERR_READONLY,
                    "scatter into an EMPTY read-only array -> READONLY (S5)");
            nd_release(&er); nd_release(&e); nd_release(&ie);
        }
    }
    // internal overlap of the destination (stride 0)
    {
        ndarr_t d0 = {0};
        make_desc(&d0, dst.data, OTI_F64, 2, sh, (int64_t[]){0, 1}, ND_WRITEABLE);
        nd_wrap(NULL, &d0, NULL, -1, NULL, NULL, &ov);
        it[0] = arr_item(&i2);
        {
            ndarr_t row = {0};
            int64_t s24[2] = {2, 4};
            double rowv[8] = {0};
            make_from(2, s24, ND_LAYOUT_C, rowv, &row);
            check(nd_index_set(NULL, &ov, 1, it, &row) == OTI_ERR_LAYOUT,
                    "scatter into a destination with stride 0 -> LAYOUT");
            nd_release(&row);
        }
        nd_release(&ov);
    }
    // out-of-range / float / mask errors on the scatter path leave dst untouched
    {
        int64_t bad[1] = {9};
        ndarr_t ib = {0};
        double snap[12];
        nd_wrap_trusted(bad, OTI_I64, 1, (int64_t[]){1}, NULL, 0, &ib);
        it[0] = arr_item(&ib);
        for (i = 0; i < 12; i++){
            snap[i] = get_f(&dst, i);
        }
        {
            ndarr_t one = {0};
            double ov1[4] = {1, 2, 3, 4};
            make_from(1, (int64_t[]){4}, ND_LAYOUT_C, ov1, &one);
            check(nd_index_set(NULL, &dst, 1, it, &one) == OTI_ERR_INDEX,
                    "scatter at index 9 on extent 3 -> INDEX");
            nd_release(&one);
        }
        {
            int ok = 1;
            for (i = 0; i < 12; i++){
                ok = ok && get_f(&dst, i) == snap[i];
            }
            check(ok, "a failed scatter (out of range) wrote nothing");
        }
        it[0] = arr_item(&f2);
        {
            ndarr_t one = {0};
            double ov1[4] = {1, 2, 3, 4};
            make_from(1, (int64_t[]){4}, ND_LAYOUT_C, ov1, &one);
            check(nd_index_set(NULL, &dst, 1, it, &one) == OTI_ERR_DTYPE,
                    "scatter with a float index array -> DTYPE");
            nd_release(&one);
        }
    }
    // the snapshot rule: values overlapping dst are copied first.
    //   d = np.arange(12.).reshape(3,4); d[[1,2]] = d[:2]   ->  rows [0,1,2,3],[0,1,2,3],[4,5,6,7]
    {
        double expect[12] = {0, 1, 2, 3, 0, 1, 2, 3, 4, 5, 6, 7};
        int64_t r12[2] = {1, 2};
        ndarr_t ir = {0}, head = {0};
        nd_index_t hx[1];
        int ok = 1;
        nd_wrap_trusted(r12, OTI_I64, 1, s2, NULL, 0, &ir);
        for (i = 0; i < 12; i++){
            set_f(&dst, i, (double)i);
        }
        hx[0] = kind_item(ND_IDX_SLICE);
        hx[0].has = HP;
        hx[0].stop = 2;
        nd_view_index(&dst, 1, hx, &head);
        it[0] = arr_item(&ir);
        check(nd_index_set(NULL, &dst, 1, it, &head) == OTI_OK,
                "d[[1,2]] = d[:2]: values overlap the destination");
        for (i = 0; i < 12; i++){
            ok = ok && get_f(&dst, i) == expect[i];
        }
        check(ok,
                "d[[1,2]] = d[:2] gives [[0,1,2,3],[0,1,2,3],[4,5,6,7]] (NumPy copies the values first)");
        // the temporary is charged to the temp budget
        oti_ctx_init(&ctx);
        ctx.max_temp_bytes = 1;
        for (i = 0; i < 12; i++){
            set_f(&dst, i, (double)i);
        }
        check(nd_index_set(&ctx, &dst, 1, it, &head) == OTI_ERR_MEMORY,
                "the snapshot copy with a 1-byte temp budget -> MEMORY");
        {
            int unchanged = 1;
            for (i = 0; i < 12; i++){
                unchanged = unchanged && get_f(&dst, i) == (double)i;
            }
            check(unchanged, "... and dst is untouched");
        }
        nd_test_fail_alloc(1);
        {
            int st = nd_index_set(NULL, &dst, 1, it, &head);
            nd_test_fail_alloc(0);
            check(st == OTI_ERR_MEMORY,
                    "the snapshot copy with an injected allocation failure -> MEMORY");
        }
    }
    // bad context
    oti_ctx_init(&ctx);
    ctx.device_type = 2;
    it[0] = arr_item(&i2);
    check(nd_index_set(&ctx, &dst, 1, it, &f2) == oti_ctx_check(&ctx),
            "scatter with a bad context is rejected");
    oti_ctx_init(&ctx);
    check(nd_index_set(&ctx, &dst, 1, it, &f2) == OTI_ERR_SHAPE && oti_ctx_last_error(&ctx, NULL,
            NULL) == OTI_ERR_SHAPE,
          "a failing nd_index_set records its status");
    (void)vals;
    nd_release(&base);

}
