// *******************************************************************************************************
static void test_set_dtypes(void){

    ndarr_t bi = {0}, di = {0}, bu = {0}, du = {0}, iv = {0}, uv = {0}, ix = {0};
    int64_t s6[1] = {6}, s2[1] = {2};
    int64_t d[2] = {1, 4};
    int64_t v64[2] = {-5, 99};
    uint8_t vu[2] = {200, 3};
    nd_index_t it[1];
    int64_t i;

    nd_wrap_trusted(d, OTI_I64, 1, s2, NULL, 0, &ix);
    it[0] = arr_item(&ix);
    nd_wrap_trusted(v64, OTI_I64, 1, s2, NULL, 0, &iv);
    nd_wrap_trusted(vu, OTI_U8, 1, s2, NULL, 0, &uv);

    // I64 destination, I64 values: d = np.arange(6); d[[1,4]] = [-5, 99]  -> [0,-5,2,3,99,5]
    make_view(1, s6, 0, OTI_I64, &bi, &di);
    for (i = 0; i < 6; i++){
        ((int64_t*)di.data)[i] = i;
    }
    check(nd_index_set(NULL, &di, 1, it, &iv) == OTI_OK && ((int64_t*)di.data)[1] == -5 &&
            ((int64_t*)di.data)[4] == 99 &&
          ((int64_t*)di.data)[5] == 5, "I64 destination, I64 values: [0,-5,2,3,99,5]");
    // U8 destination, U8 values
    make_view(1, s6, 0, OTI_U8, &bu, &du);
    for (i = 0; i < 6; i++){
        ((uint8_t*)du.data)[i] = (uint8_t)i;
    }
    check(nd_index_set(NULL, &du, 1, it, &uv) == OTI_OK && ((uint8_t*)du.data)[1] == 200 &&
            ((uint8_t*)du.data)[4] == 3,
          "U8 destination, U8 values: [0,200,2,3,3,5]");
    // I64 values into an F64 destination: np.arange(6.)[[1,4]] = np.array([-5, 99])
    {
        ndarr_t bf = {0}, df = {0};
        make_view(1, s6, 0, OTI_F64, &bf, &df);
        for (i = 0; i < 6; i++){
            set_f(&df, i, (double)i);
        }
        check(nd_index_set(NULL, &df, 1, it, &iv) == OTI_OK && get_f(&df, 1) == -5.0 && get_f(&df,
                4) == 99.0,
              "I64 values into an F64 destination convert numerically");
        check(nd_index_set(NULL, &df, 1, it, &uv) == OTI_OK && get_f(&df, 1) != 0.0,
              "U8 values into an F64 destination are accepted");
        nd_release(&bf);
    }
    // F64 values into U8 / I64 destinations are DTYPE
    {
        ndarr_t fv = {0};
        double f2[2] = {1.0, 2.0};
        nd_wrap_trusted(f2, OTI_F64, 1, s2, NULL, 0, &fv);
        check(nd_index_set(NULL, &du, 1, it, &fv) == OTI_ERR_DTYPE,
                "F64 values into a U8 destination -> DTYPE");
    }
    nd_release(&bi);
    nd_release(&bu);

}
