// *******************************************************************************************************
// Budgets and allocation failures of the gather (no leaks: the lead runs leaks and ASan).
static void test_get_budget_and_fail_alloc(void){

    ndarr_t base = {0}, src = {0}, res = {0}, ix = {0};
    int64_t sh[2] = {100, 100}, s1[1] = {50};
    int64_t d[50];
    nd_index_t it[2];
    oti_ctx ctx;
    int64_t i;
    int k, saw = 0, finished = 0, ok = 1;

    for (i = 0; i < 50; i++){
        d[i] = i * 2;
    }
    make_src(2, sh, 0, &base, &src);
    nd_wrap_trusted(d, OTI_I64, 1, s1, NULL, 0, &ix);
    it[0] = arr_item(&ix);
    it[1] = kind_item(ND_IDX_SLICE);                    // a[d, :] is (50, 100) doubles = 40000 bytes
    oti_ctx_init(&ctx);
    ctx.max_alloc_bytes = 39999;
    nd_init_empty(&res);
    check(nd_index_get(&ctx, &src, 2, it, &res) == OTI_ERR_MEMORY && res.buf == NULL,
          "a gather of 40000 bytes with max_alloc_bytes = 39999 -> MEMORY, res empty");
    ctx.max_alloc_bytes = 40000;
    check(nd_index_get(&ctx, &src, 2, it, &res) == OTI_OK && res.shape[0] == 50 && res.shape[1] == 100,
          "... and with exactly 40000 bytes it succeeds");
    nd_release(&res);
    // the index array count alone can be too large: a mask over a big source builds its nonzero lists
    for (k = 1; k < 20 && !finished; k++){
        int st;
        nd_init_empty(&res);
        nd_test_fail_alloc(k);
        st = nd_index_get(NULL, &src, 2, it, &res);
        nd_test_fail_alloc(0);
        if (st == OTI_OK){
            finished = 1;
            nd_release(&res);
        } else {
            saw++;
            ok = ok && st == OTI_ERR_MEMORY && res.buf == NULL;
        }
    }
    check(saw >= 1 && finished && ok,
            "nd_index_get fail_alloc: every allocation can fail: MEMORY, an empty res, then success");
    // a mask gather allocates the nonzero lists too
    {
        ndarr_t bm = {0}, vm = {0};
        int sawm = 0, finm = 0, okm = 1;
        make_view(2, sh, 0, OTI_U8, &bm, &vm);
        for (i = 0; i < 10000; i++){
            set_num(&vm, i, (double)(i % 3 == 0));
        }
        it[0] = arr_item(&vm);
        for (k = 1; k < 20 && !finm; k++){
            int st;
            nd_init_empty(&res);
            nd_test_fail_alloc(k);
            st = nd_index_get(NULL, &src, 1, it, &res);
            nd_test_fail_alloc(0);
            if (st == OTI_OK){
                finm = 1;
                okm = okm && res.shape[0] == 3334;
                nd_release(&res);
            } else {
                sawm++;
                okm = okm && st == OTI_ERR_MEMORY && res.buf == NULL;
            }
        }
        check(sawm >= 1 && finm && okm,
                "mask gather fail_alloc: MEMORY with an empty res at every allocation, then success");
        {
            oti_ctx tight;
            oti_ctx_init(&tight);
            tight.max_alloc_bytes = 8;
            check(nd_index_get(&tight, &src, 1, it, &res) == OTI_ERR_MEMORY && res.buf == NULL,
                  "mask gather with an 8-byte allocation budget -> MEMORY");
        }
        nd_release(&bm);
    }
    // scatter: fail_alloc with a mask (the nonzero lists) leaves dst unchanged
    {
        ndarr_t bm = {0}, vm = {0}, vals = {0};
        double one = 5.0;
        int sawm = 0, finm = 0, okm = 1;
        (void)sawm;
        make_view(2, sh, 0, OTI_U8, &bm, &vm);
        for (i = 0; i < 10000; i++){
            set_num(&vm, i, (double)(i % 7 == 0));
        }
        it[0] = arr_item(&vm);
        make_from(0, NULL, ND_LAYOUT_C, &one, &vals);
        for (k = 1; k < 20 && !finm; k++){
            int st;
            for (i = 0; i < 10000; i++){
                set_f(&src, i, (double)i);
            }
            nd_test_fail_alloc(k);
            st = nd_index_set(NULL, &src, 1, it, &vals);
            nd_test_fail_alloc(0);
            if (st == OTI_OK){
                finm = 1;
                okm = okm && get_f(&src, 0) == 5.0 && get_f(&src, 1) == 1.0 && get_f(&src, 7) == 5.0;
            } else {
                int unchanged = 1;
                sawm++;
                for (i = 0; i < 10000; i++){
                    unchanged = unchanged && get_f(&src, i) == (double)i;
                }
                okm = okm && st == OTI_ERR_MEMORY && unchanged;
            }
        }
        check(finm && okm, "mask scatter fail_alloc: MEMORY with dst unchanged, then the right result");
        nd_release(&bm);
        nd_release(&vals);
    }
    nd_release(&base);

}
