// *******************************************************************************************************
int main(void){

    test_get_numpy_cases();
    test_set_numpy_cases();
    test_get_random();
    test_set_random();
    test_get_errors();
    test_get_dtypes_and_masks();
    test_set_errors_and_overlap();
    test_set_dtypes();
    test_get_budget_and_fail_alloc();

    if (n_failed > 0){
        fprintf(stderr, "\n%d check(s) FAILED\n", n_failed);
        return 1;
    }
    printf("\nAll checks passed.\n");
    return 0;

}
